    c1 = f.read()

import re
files = re.split(r'={10,}\nFile:\s*([^\n]+)\n={10,}', c1)
parsed_files = {}
for i in range(1, len(files), 2):
    parsed_files[files[i].strip()] = files[i+1]

for fname, content in parsed_files.items():
    if 'שם מושג הוא' in content:
        print(f"Found in {fname}")

